CREATE TABLE parcels (
    id number(19) GENERATED BY DEFAULT AS IDENTITY,
    tracking_number varchar2(20) NOT NULL UNIQUE,
    depot_code varchar2(10) CONSTRAINT parcels_depot_fk REFERENCES depots (code),
    weight_grams number(10),
    weight_kg number GENERATED ALWAYS AS (weight_grams / 1000) VIRTUAL,
    status varchar2(20) DEFAULT 'registered' NOT NULL,
    "ORDER" varchar2(32),
    label_note varchar2(100) DEFAULT 'fragile -- handle with care; don''t stack',
    sender_name varchar2(100),
    CONSTRAINT parcels_pk PRIMARY KEY (id)
);

CREATE INDEX parcels_status_idx ON parcels (status);

COMMENT ON TABLE parcels IS 'A parcel''s journey; from depot to door';
COMMENT ON COLUMN parcels."ORDER" IS q'[The shop's order number -- as the sender gave it]';
